using System;using System.Reflection;using System.Windows.Forms;
class StartupTest{[STAThread]static void Main(string[] args){var assembly=Assembly.LoadFrom(args[0]);var factory=assembly.GetType("SetupForm").GetMethod("CreateStartupForm",BindingFlags.Static|BindingFlags.NonPublic);using(var form=(Form)factory.Invoke(null,new object[]{new[]{"/settings"}})){if(form.GetType().Name!="SoundSettingsForm")throw new Exception("Settings launch returned installer");form.Show();Application.DoEvents();int visible=0;foreach(Form window in Application.OpenForms){if(window.Visible){visible++;if(window.GetType().Name!="SoundSettingsForm")throw new Exception("Installer is visible");}}if(visible!=1)throw new Exception("Expected exactly one visible window");form.Close();}using(var form=(Form)factory.Invoke(null,new object[]{new string[0]})){if(form.GetType().Name!="SetupForm")throw new Exception("Installer entry changed");}Console.WriteLine("PASS: /settings shows only Sound Settings; default entry remains installer.");}}
